			err:      errs.ErrNotFound("flag"),
			wantCode: codes.NotFound,
		},
		{
			name:     "invalid error",
			ctx:      context.Background,
			err:      errs.ErrInvalid("bad value"),
			wantCode: codes.InvalidArgument,
		},
		{
			name:     "unauthenticated error",
			ctx:      context.Background,
			err:      errs.ErrUnauthenticated("bad token"),
			wantCode: codes.Unauthenticated,
		},
		{
			name:     "generic error",
			ctx:      context.Background,
			err:      errors.New("unknown error"),
			wantCode: codes.Internal,
		},
		{
			name:     "existing status error unchanged",
			ctx:      context.Background,
			err:      status.Error(codes.PermissionDenied, "forbidden"),
			wantCode: codes.PermissionDenied,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			spyHandler := grpc.UnaryHandler(func(ctx context.Context, req interface{}) (interface{}, error) {
				return nil, tt.err
			})

			ctx := tt.ctx()
			_, err := ErrorUnaryInterceptor(ctx, nil, nil, spyHandler)
			require.Error(t, err)
			st := status.Convert(err)
			assert.Equal(t, tt.wantCode, st.Code())
		})
	}
}

func TestAuthUnaryInterceptor_ContextErrors(t *testing.T) {
	logger := zaptest.NewLogger(t)

	tests := []struct {
		name        string
		ctx         func() context.Context
		md          metadata.MD
		mockAuth    func(ctx context.Context, clientToken string) (*authrpc.Authentication, error)
		wantCode    codes.Code
		wantAuthNil bool
	}{
		{
			name: "authenticator returns context.Canceled",
			ctx:  context.Background,
			md: metadata.MD{
				"authorization": []string{"Bearer valid-token"},
			},
			mockAuth: func(ctx context.Context, clientToken string) (*authrpc.Authentication, error) {
				return nil, context.Canceled
			},
			wantCode:    codes.Canceled,
			wantAuthNil: true,
		},
		{
			name: "authenticator returns wrapped context.Canceled",
			ctx:  context.Background,
			md: metadata.MD{
				"authorization": []string{"Bearer valid-token"},
			},
			mockAuth: func(ctx context.Context, clientToken string) (*authrpc.Authentication, error) {
				return nil, fmt.Errorf("querying auth store: %w", context.Canceled)
			},
			wantCode:    codes.Canceled,
			wantAuthNil: true,
		},
		{
			name: "authenticator returns errs.ErrCanceled",
			ctx:  context.Background,
			md: metadata.MD{
				"authorization": []string{"Bearer valid-token"},
			},
			mockAuth: func(ctx context.Context, clientToken string) (*authrpc.Authentication, error) {
				return nil, errs.ErrCanceled("query canceled")
			},
			wantCode:    codes.Canceled,
			wantAuthNil: true,
		},
		{
			name: "authenticator returns context.DeadlineExceeded",
			ctx:  context.Background,
			md: metadata.MD{
				"authorization": []string{"Bearer valid-token"},
			},
			mockAuth: func(ctx context.Context, clientToken string) (*authrpc.Authentication, error) {
				return nil, context.DeadlineExceeded
			},
			wantCode:    codes.DeadlineExceeded,
			wantAuthNil: true,
		},
		{
			name: "authenticator returns wrapped context.DeadlineExceeded",
			ctx:  context.Background,
			md: metadata.MD{
				"authorization": []string{"Bearer valid-token"},
			},
			mockAuth: func(ctx context.Context, clientToken string) (*authrpc.Authentication, error) {
				return nil, fmt.Errorf("getting auth: %w", context.DeadlineExceeded)
			},
			wantCode:    codes.DeadlineExceeded,
			wantAuthNil: true,
		},
		{
			name: "context already canceled before call",
			ctx: func() context.Context {
				c, cancel := context.WithCancel(context.Background())
				cancel()
				return c
			},
			md: metadata.MD{
				"authorization": []string{"Bearer valid-token"},
			},
			mockAuth: func(ctx context.Context, clientToken string) (*authrpc.Authentication, error) {
				return nil, nil
			},
			wantCode:    codes.Canceled,
			wantAuthNil: true,
		},
		{
			name: "context deadline exceeded before call",
			ctx: func() context.Context {
				c, cancel := context.WithDeadline(context.Background(), time.Now().Add(-time.Second))
				defer cancel()
				return c
			},
			md: metadata.MD{
				"authorization": []string{"Bearer valid-token"},
			},
			mockAuth: func(ctx context.Context, clientToken string) (*authrpc.Authentication, error) {
				return nil, nil
			},
			wantCode:    codes.DeadlineExceeded,
			wantAuthNil: true,
		},
		{
			name: "authenticator returns standard not found error",
			ctx:  context.Background,
			md: metadata.MD{
				"authorization": []string{"Bearer invalid-token"},
			},
			mockAuth: func(ctx context.Context, clientToken string) (*authrpc.Authentication, error) {
				return nil, errors.New("token not found")
			},
			wantCode:    codes.Unauthenticated,
			wantAuthNil: true,
		},
		{
			name: "successful authentication",
			ctx:  context.Background,
			md: metadata.MD{
				"authorization": []string{"Bearer valid-token"},
			},
			mockAuth: func(ctx context.Context, clientToken string) (*authrpc.Authentication, error) {
				return &authrpc.Authentication{Id: "test-auth-id"}, nil
			},
			wantCode:    codes.OK,
			wantAuthNil: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			authenticator := &mockAuthenticator{
				getAuthFunc: tt.mockAuth,
			}

			var retrievedAuth *authrpc.Authentication
			handler := func(ctx context.Context, req interface{}) (interface{}, error) {
				retrievedAuth = auth.GetAuthenticationFrom(ctx)
				return "ok", nil
			}

			ctx := tt.ctx()
			if tt.md != nil {
				ctx = metadata.NewIncomingContext(ctx, tt.md)
			}

			resp, err := auth.UnaryInterceptor(logger, authenticator)(
				ctx,
				nil,
				&grpc.UnaryServerInfo{},
				handler,
			)

			if tt.wantCode == codes.OK {
				require.NoError(t, err)
				assert.Equal(t, "ok", resp)
				assert.NotNil(t, retrievedAuth)
				assert.Equal(t, "test-auth-id", retrievedAuth.Id)
			} else {
				require.Error(t, err)
				st := status.Convert(err)
				assert.Equal(t, tt.wantCode, st.Code(), "expected code %v but got %v: %v", tt.wantCode, st.Code(), err)
			}
		})
	}
}
